fn validate_invocation_context(headers: &HeaderMap) -> Result<Context, InvocationError> {
    let component = headers.get("component").ok_or(InvocationError::MissingComponent)?;
    let tracing_metadata = headers.get("tracing-metadata").ok_or(InvocationError::MissingTracingMetadata)?;

    let component_str = component.to_str().map_err(|e| InvocationError::InvalidComponent(e.to_string()))?;
    let tracing_metadata_str = tracing_metadata.to_str().map_err(|e| InvocationError::InvalidTracingMetadata(e.to_string()))?;

    Ok(Context {
        component: component_str.to_string(),
        tracing_metadata: tracing_metadata_str.to_string(),
    })
}

