use std::fs;
use std::path::{Path, PathBuf};
use serde_json_canonicalizer::pipe;

fn batch_convert_json_to_jcs(directory: &str) -> std::io::Result<()> {
    if !Path::new(directory).exists() {
        return Err(std::io::Error::new(std::io::ErrorKind::NotFound, format!("Directory not found: {}", directory)));
    }

    let entries = fs::read_dir(directory)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext == "json") {
            let content = fs::read_to_string(&path)?;
            let canonicalized = pipe(&content);
            let new_path = path.with_extension("jcs");

            fs::write(new_path, canonicalized)?;
        }
    }

    Ok(())
}

fn persist_state<T: Target>(router: &RouterContext<T>, state: State) -> State {
    if let Some(window) = window() {
        let storage = window.local_storage().ok_or(JsValue::from_str("Local storage not available")).unwrap();
        let serialized = serde_wasm_bindgen::to_value(&state).map_err(|e| JsValue::from_str(&format!("Serialization error: {}", e)));
        storage.set_item("router_state", &serialized).ok();
    }

    if let Some(window) = window() {
        let storage = window.local_storage().ok_or(JsValue::from_str("Local storage not available")).unwrap();
        if let Ok(value) = storage.get_item("router_state") {
            if let Ok(deserialized) = serde_wasm_bindgen::from_value(value) {
                return deserialized;
            }
        }
    }

    state
}

use crate::ast::{Root, Lambda, Apply};
use crate::match_ast;
use crate::SyntaxNode;

fn extract_functions(root: &Root) -> Vec<Lambda> {
    let mut functions = Vec::new();
    match_ast! { root,
        |Apply { func, .. }| {
            if let Some(lambda) = func.as_ref() {
                if let SyntaxNode::Lambda(lambda) = lambda {
                    functions.push(lambda.clone());
                }
            }
        },
        |Lambda(lambda)| {
            functions.push(lambda.clone());
        }
    };
    functions
}

use std::io;
use std::error::Error;
use ext_sort::{ExternalSorter, SortError};

fn process_sorted_in_batches<T, E, F>(
    sorter: &ExternalSorter<T, E>,
    input: impl IntoIterator<Item = Result<T, E>>,
    batch_size: usize,
    mut processor: F,
) -> Result<(), SortError<E, E, E>>
where
    T: Ord + Clone + Send,
    F: FnMut(&[T]) -> Result<(), io::Error>,
    E: Error,
{
    let mut buffer = Vec::new();
    let mut input_iter = input.into_iter();

    while let Some(result) = input_iter.next() {
        let item = result?;
        buffer.push(item);

        if buffer.len() >= batch_size {
            processor(&buffer)?;
            buffer.clear();
        }
    }

    if !buffer.is_empty() {
        processor(&buffer)?;
    }

    Ok(())
}

use crate::highlight::{HighlightConfiguration, Highlighter, HighlightEvent, Error};

fn highlight_with_injections(
    config: &HighlightConfiguration,
    source: &[u8],
    get_injection: impl Fn(&str) -> Option<&HighlightConfiguration>,
) -> Result<Vec<HighlightEvent>, Error> {
    let mut highlighter = Highlighter::new(config);
    let mut events = Vec::new();

    for event in highlighter.highlight(source) {
        match event {
            Ok(event) => {
                events.push(event);
                if let Some(injection_config) = get_injection(&event.language) {
                    // Recursively highlight injected content
                    let mut injection_highlighter = Highlighter::new(injection_config);
                    let injection_source = &event.content;
                    for injection_event in injection_highlighter.highlight(injection_source) {
                        match injection_event {
                            Ok(injection_event) => {
                                events.push(injection_event);
                            }
                            Err(e) => return Err(e),
                        }
                    }
                }
            }
            Err(e) => return Err(e),
        }
    }

    Ok(events)
}

