fn report_issued_notes_by_denomination(dbtx: &mut DatabaseTransaction<'_>) -> BTreeMap<Amount, Amount> {
    let mut report = BTreeMap::new();
    let prefix = MintAuditItemKeyPrefix::Issued;
    let mut iter = dbtx.iter_prefix(prefix);

    while let Some((key, value)) = iter.next() {
        if let Some(denomination) = MintAuditItemKey::from_key(key).map(|k| k.denomination) {
            let amount = *value;
            *report.entry(denomination).or_insert(Amount::zero()) += amount;
        }
    }

    report
}

fn cose_key_to_jwk(key: &CoseKey) -> Result<serde_json::Value, KeyDecodingError> {
    let mut jwk = serde_json::Map::new();
    let key_type = match key.key_type() {
        KeyType::EC2 => "EC2",
        KeyType::OKP => "OKP",
        _ => return Err(KeyDecodingError::UnsupportedKeyType),
    };
    jwk.insert(serde_json::json!("kty"), serde_json::json!(key_type));

    match key.key_type() {
        KeyType::EC2 => {
            let crv = match key.get(Label::Crv) {
                Some(crv) => match crv {
                    coset::CoseKeyParameter::OctetString(crv) => {
                        let crv_str = String::from_utf8_lossy(crv);
                        if let Some(crv) = EC2_CRV.get(crv_str.as_ref()) {
                            crv.to_string()
                        } else {
                            return Err(KeyDecodingError::InvalidCurve);
                        }
                    }
                    _ => return Err(KeyDecodingError::InvalidParameter),
                },
                None => return Err(KeyDecodingError::MissingParameter),
            };
            jwk.insert(serde_json::json!("crv"), serde_json::json!(crv));

            let x = match key.get(Label::X) {
                Some(x) => match x {
                    coset::CoseKeyParameter::OctetString(x) => {
                        let x_str = URL_SAFE_NO_PAD.encode(x);
                        serde_json::Value::String(x_str)
                    }
                    _ => return Err(KeyDecodingError::InvalidParameter),
                },
                None => return Err(KeyDecodingError::MissingParameter),
            };
            jwk.insert(serde_json::json!("x"), x);

            let y = match key.get(Label::Y) {
                Some(y) => match y {
                    coset::CoseKeyParameter::OctetString(y) => {
                        let y_str = URL_SAFE_NO_PAD.encode(y);
                        serde_json::Value::String(y_str)
                    }
                    _ => return Err(KeyDecodingError::InvalidParameter),
                },
                None => return Err(KeyDecodingError::MissingParameter),
            };
            jwk.insert(serde_json::json!("y"), y);
        }
        KeyType::OKP => {
            let crv = match key.get(Label::Crv) {
                Some(crv) => match crv {
                    coset::CoseKeyParameter::OctetString(crv) => {
                        let crv_str = String::from_utf8_lossy(crv);
                        if let Some(crv) = OKP_CRV.get(crv_str.as_ref()) {
                            crv.to_string()
                        } else {
                            return Err(KeyDecodingError::InvalidCurve);
                        }
                    }
                    _ => return Err(KeyDecodingError::InvalidParameter),
                },
                None => return Err(KeyDecodingError::MissingParameter),
            };
            jwk.insert(serde_json::json!("crv"), serde_json::json!(crv));

            let x = match key.get(Label::X) {
                Some(x) => match x {
                    coset::CoseKeyParameter::OctetString(x) => {
                        let x_str = URL_SAFE_NO_PAD.encode(x);
                        serde_json::Value::String(x_str)
                    }
                    _ => return Err(KeyDecodingError::InvalidParameter),
                },
                None => return Err(KeyDecodingError::MissingParameter),
            };
            jwk.insert(serde_json::json!("x"), x);
        }
        _ => return Err(KeyDecodingError::UnsupportedKeyType),
    }

    Ok(serde_json::Value::Object(jwk))
}

use ssi_eip712::{value::Value, ty::{TypeRef, Types}, hashing::TypedDataHashError};

fn validate_value(value: &Value, type_ref: &TypeRef, types: &Types) -> Result<(), TypedDataHashError> {
    match type_ref {
        TypeRef::Bool => match value {
            Value::Bool(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Int => match value {
            Value::Int(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Uint => match value {
            Value::Uint(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::String => match value {
            Value::String(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Array => {
            if let Value::Array(arr) = value {
                if let Some(inner_type) = type_ref.array_type() {
                    for item in arr {
                        validate_value(item, inner_type, types)?;
                    }
                } else {
                    return Err(TypedDataHashError::InvalidType);
                }
                Ok(())
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Map => {
            if let Value::Map(map) = value {
                if let Some(inner_type) = type_ref.map_type() {
                    for (key, val) in map {
                        validate_value(key, inner_type.key_type(), types)?;
                        validate_value(val, inner_type.value_type(), types)?;
                    }
                } else {
                    return Err(TypedDataHashError::InvalidType);
                }
                Ok(())
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Enum => {
            if let Value::Enum(e) = value {
                if let Some(enum_type) = types.get(type_ref.name()) {
                    if let Some(variants) = enum_type.variants() {
                        if variants.contains(e) {
                            Ok(())
                        } else {
                            Err(TypedDataHashError::InvalidEnumVariant)
                        }
                    } else {
                        Err(TypedDataHashError::InvalidType)
                    }
                } else {
                    Err(TypedDataHashError::InvalidType)
                }
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Struct => {
            if let Value::Struct(map) = value {
                if let Some(struct_type) = types.get(type_ref.name()) {
                    if let Some(fields) = struct_type.fields() {
                        for (field_name, field_type) in fields {
                            if let Some(val) = map.get(field_name) {
                                validate_value(val, field_type, types)?;
                            } else {
                                return Err(TypedDataHashError::MissingField(field_name.to_string()));
                            }
                        }
                    } else {
                        return Err(TypedDataHashError::InvalidType);
                    }
                } else {
                    return Err(TypedDataHashError::InvalidType);
                }
                Ok(())
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        _ => Err(TypedDataHashError::InvalidType),
    }
}

