fn cleanup_expired_gateways(dbtx: &mut DatabaseTransaction<'_>) -> anyhow::Result<()> {
    let mut stream = dbtx.scan_prefix(LightningGatewayKeyPrefix::Registration);
    let mut deleted_count = 0;

    while let Some(item) = stream.next().await {
        let (key, value) = item?;
        let registration: LightningGatewayRegistration = value?;

        if registration.is_expired() {
            dbtx.delete(key)?;
            deleted_count += 1;
        }
    }

    tracing::info!("Deleted {} expired gateway registrations", deleted_count);
    Ok(())
}

fn analyze_tokens(tokens: &[String]) -> Vec<(String, TokenType)> {
    let mut result = Vec::new();
    for token in tokens {
        let token_type = determine_token_type(token);
        result.push((token.clone(), token_type));
    }
    result
}

enum TokenType {
    Kanji,
    Hiragana,
    Katakana,
    Alphabet,
    Number,
    Other,
}

fn determine_token_type(token: &str) -> TokenType {
    let mut has_kanji = false;
    let mut has_hiragana = false;
    let mut has_katakana = false;
    let mut has_alphabet = false;
    let mut has_number = false;

    for c in token.chars() {
        let ctype = get_ctype(c);
        match ctype {
            'M' => has_kanji = true,
            'H' => has_hiragana = true,
            'I' => has_hiragana = true,
            'K' => has_katakana = true,
            'A' => has_alphabet = true,
            'N' => has_number = true,
            _ => {}
        }
    }

    if has_kanji {
        return TokenType::Kanji;
    } else if has_hiragana {
        return TokenType::Hiragana;
    } else if has_katakana {
        return TokenType::Katakana;
    } else if has_alphabet {
        return TokenType::Alphabet;
    } else if has_number {
        return TokenType::Number;
    } else {
        return TokenType::Other;
    }
}

use deno_core::OpState;
use deno_os::ops::signal::{op_signal_bind, op_signal_poll};
use deno_os::SignalError;

struct SignalHandler {
    callbacks: Vec<Box<dyn Fn() + Send + Sync + 'static>>,
    bound: bool,
}

impl SignalHandler {
    fn new() -> Self {
        SignalHandler {
            callbacks: Vec::new(),
            bound: false,
        }
    }

    fn bind(&mut self) -> Result<(), SignalError> {
        if !self.bound {
            op_signal_bind()?;
            self.bound = true;
        }
        Ok(())
    }

    fn add_callback<F>(&mut self, cb: F)
    where
        F: Fn() + Send + Sync + 'static,
    {
        self.callbacks.push(Box::new(cb));
    }

    fn remove_callback<F>(&mut self, cb: F)
    where
        F: Fn() + Send + Sync + 'static,
    {
        self.callbacks.retain(|c| !std::ptr::eq(c as *const _, cb as *const _));
    }

    fn trigger_callbacks(&self) {
        for cb in &self.callbacks {
            cb();
        }
    }
}

impl OpState {
    fn add_callback<F>(&mut self, cb: F)
    where
        F: Fn() + Send + Sync + 'static,
    {
        let handler = self
            .borrow_mut::<SignalHandler>()
            .unwrap_or_else(SignalHandler::new);
        handler.add_callback(cb);
    }

    fn remove_callback<F>(&mut self, cb: F)
    where
        F: Fn() + Send + Sync + 'static,
    {
        let handler = self
            .borrow_mut::<SignalHandler>()
            .unwrap_or_else(SignalHandler::new);
        handler.remove_callback(cb);
    }

    fn trigger_callbacks(&self) {
        let handler = self
            .borrow::<SignalHandler>()
            .unwrap_or_else(SignalHandler::new);
        handler.trigger_callbacks();
    }
}

