fn calculate_lightning_liabilities(
    &self,
    dbtx: &mut DatabaseTransaction<'_>,
) -> (Amount, Amount) {
    let (incoming_total, outgoing_total) = dbtx
        .iter_prefix(LightningAuditItemKeyPrefix)
        .map(|item| {
            let key: LightningAuditItemKey = item.key().try_into().unwrap();
            let amount = item.value().amount();
            (key.direction, amount)
        })
        .fold((Amount::ZERO, Amount::ZERO), |(in_total, out_total), (direction, amount)| {
            match direction {
                fedimint_core::LightningAuditDirection::Incoming => (in_total + amount, out_total),
                fedimint_core::LightningAuditDirection::Outgoing => (in_total, out_total + amount),
            }
        });

    (incoming_total, outgoing_total)
}

fn enqueue_batch(&mut self, keys: &[K], payloads: &[P]) -> Result<(), Box<dyn std::error::Error + Sync + Send>> 
where
    K: Serialize + std::hash::Hash + std::cmp::Eq + std::fmt::Debug,
    P: Serialize + DeserializeOwned + std::fmt::Debug,
    Self: CanTaskEnqueue + Expose,
{
    if keys.len() != payloads.len() {
        return Err("Keys and payloads slices must be of the same length".into());
    }

    for (key, payload) in keys.iter().zip(payloads.iter()) {
        let task_item = MemorixTaskItem {
            key: key.clone(),
            payload: payload.clone(),
        };

        self.enqueue(&task_item)?;
    }

    Ok(())
}

use gluesql_core::store::{StoreMut, DataRow};
use gluesql_core::data::Value;
