use futures::stream::TryStreamExt;

fn validate_column_type(store: &dyn StoreMut, table_name: &str, column_name: &str, expected_type: &str) -> Result<()> {
    let mut rows = store.scan(table_name).try_stream()?;
    while let Some(row) = rows.next().await {
        let row = row?;
        if let Some(value) = row.get(column_name) {
            if !matches_value(value, expected_type) {
                return Err(format!("Mismatched type for column '{}': expected '{}', got '{}'", column_name, expected_type, value).into());
            }
        }
    }
    Ok(())
}

fn matches_value(value: &Value, expected_type: &str) -> bool {
    match value {
        Value::Int(i) => expected_type == "INT" || expected_type == "INTEGER",
        Value::BigInt(i) => expected_type == "BIGINT",
        Value::Float(f) => expected_type == "FLOAT" || expected_type == "DOUBLE",
        Value::String(s) => expected_type == "STRING" || expected_type == "VARCHAR",
        Value::Bool(b) => expected_type == "BOOLEAN",
        Value::Date(d) => expected_type == "DATE",
        Value::Timestamp(t) => expected_type == "TIMESTAMP",
        Value::Null => expected_type == "NULL",
        _ => false,
    }
}

use libdeflater::{Compressor, Decompressor, CompressionLvl};

fn compress_dynamic(input: &[u8]) -> Result<Vec<u8>, String> {
    let mut compressor = Compressor::new(CompressionLvl::BestSpeed);
    let mut compressed = Vec::new();

    match compressor.compress(input, &mut compressed) {
        Ok(_) => {
            // Finalize the compression
            let mut final_compressed = Vec::new();
            match compressor.finish(&mut final_compressed) {
                Ok(_) => {
                    compressed = final_compressed;
                    Ok(compressed)
                },
                Err(e) => Err(format!("Compression finish failed: {}", e)),
            }
        },
        Err(e) => Err(format!("Compression failed: {}", e)),
    }
}

fn net_flow_per_denomination(
    dbtx: &mut DatabaseTransaction<'_>,
) -> Result<BTreeMap<Amount, i64>, anyhow::Error> {
    let mut net_flows = BTreeMap::new();

    // Iterate over all audit items
    let audit_items = dbtx
        .iter_prefix(MintAuditItemKeyPrefix)
        .map(|item| item.map(|item| (item.0, item.1)));

    for item in audit_items {
        let (key, value) = item?;
        let MintAuditItemKey { amount, direction } = key;

        // Update the net flow for the denomination
        let count = net_flows.entry(amount).or_insert(0);
        *count += match direction {
            "issued" => 1,
            "redeemed" => -1,
            _ => 0,
        };
    }

    Ok(net_flows)
}

use std::net::SocketAddr;
use libp2p_core::multiaddr::{Multiaddr, Protocol};

fn multiaddr_to_socketaddr(addr: &Multiaddr) -> Result<SocketAddr, ()> {
    let mut iter = addr.iter();
    let mut host = None;
    let mut port = None;

    while let Some(proto) = iter.next() {
        match proto {
            Protocol::Ip4(ip) => {
                host = Some(ip.to_string());
            }
            Protocol::Ip6(ip) => {
                host = Some(ip.to_string());
            }
            Protocol::Domain(domain) => {
                host = Some(domain.to_string());
            }
            Protocol::Tcp(port) => {
                port = Some(*port);
            }
            _ => {
                // Ignore other protocols
            }
        }
    }

    let host = host.ok_or(())?;
    let port = port.ok_or(())?;

    let socket_addr = SocketAddr::new(
        host.parse().map_err(|_| ())?,
        port,
    );

    Ok(socket_addr)
}

