use dts::{Encoding, Error};
use dts::ser::SerializerBuilder;
use serde_json::Value;

fn json_to_csv_custom(value: Value) -> Result<String, dts::Error> {
    if value.is_array() {
        let array = value.as_array().unwrap();
        if let Some(first) = array.first() {
            if let Some(obj) = first.as_object() {
                let mut serializer = SerializerBuilder::new()
                    .delimiter(';')
                    .encoding(Encoding::Utf8)
                    .build();

                let header: Vec<String> = obj.keys().map(|k| k.to_string()).collect();
                serializer.serialize_value(&header)?;

                for item in array {
                    if let Some(obj) = item.as_object() {
                        let mut row = Vec::new();
                        for field in &header {
                            if let Some(val) = obj.get(field) {
                                row.push(val.to_string());
                            } else {
                                row.push("".to_string());
                            }
                        }
                        serializer.serialize_value(&row)?;
                    }
                }

                return Ok(serializer.into_string());
            }
        }
    }
    Err(Error::new("Invalid JSON array format"))
}

fn collect_stream<Req, Resp>(
    client: &RpcClient<Req, Resp>,
    request: Req,
    timeout: Option<std::time::Duration>,
) -> Result<Vec<Resp>, Error>
where
    Req: Message + Send + 'static,
    Resp: Message + Send + 'static,
{
    let mut responses = Vec::new();
    let mut stream = client.unary_stream(request)?;

    if let Some(duration) = timeout {
        let stream = Box::pin(timeout::timeout(duration, stream));
        while let Some(result) = stream.next().await {
            match result {
                Ok(response) => responses.push(response),
                Err(e) => return Err(e),
            }
        }
    } else {
        while let Some(result) = stream.next().await {
            match result {
                Ok(response) => responses.push(response),
                Err(e) => return Err(e),
            }
        }
    }

    Ok(responses)
}

fn register_gateway_safe(
    &self,
    dbtx: &mut DatabaseTransaction<'_>,
    gateway: LightningGatewayAnnouncement,
) -> Result<(), Error> {
    // Check for existing gateway with overlapping expiration
    let existing_gateways = LightningGatewayKey::iter(dbtx)
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for existing_key in existing_gateways {
        let existing_announcement = LightningGatewayKey::get(dbtx, &existing_key)
            .map_err(|e| anyhow!("Failed to retrieve existing gateway: {}", e))?;

        if overlaps(&existing_announcement.expiry, &gateway.expiry) {
            return Err(anyhow!("Gateway with overlapping expiry already exists"));
        }
    }

    // Check for expired gateways and delete them
    let expired_gateways = LightningGatewayKey::iter(dbtx)
        .filter(|(_, entry)| entry.expiry < std::time::SystemTime::now())
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for key in expired_gateways {
        LightningGatewayKey::delete(dbtx, &key)
            .map_err(|e| anyhow!("Failed to delete expired gateway: {}", e))?;
    }

    // Register the new gateway
    LightningGatewayKey::insert(dbtx, &gateway.key, &gateway)
        .map_err(|e| anyhow!("Failed to register new gateway: {}", e))?;

    Ok(())
}

fn overlaps(a: &std::time::SystemTime, b: &std::time::SystemTime) -> bool {
    let a_start = a
        .checked_sub(std::time::Duration::from_secs(3600))
        .unwrap_or(*a);
    let b_start = b
        .checked_sub(std::time::Duration::from_secs(3600))
        .unwrap_or(*b);

    let a_end = a;
    let b_end = b;

    a_start < b_end && b_start < a_end
}

fn batch_highlight(
    highlighter: &mut Highlighter,
    config: &HighlightConfiguration,
    sources: &[&[u8]],
) -> Result<Vec<String>, Error> {
    let mut results = Vec::new();
    for source in sources {
        let mut html = String::new();
        let mut renderer = HtmlRenderer::new(&mut html);
        highlighter.highlight_source(config, source, &mut renderer)?;
        results.push(html);
    }
    Ok(results)
}
